  g.TravelTo(1);yield return null;FestivalStation memory=null;foreach(var f in g.FestivalStations)if(f.Kind==FestivalKind.Memory&&f.Centre.y>0)memory=f;g.Player.Teleport(memory.Centre);memory.StartGame();memory.Tick(5.1f);var first=new List<int>();for(int i=0;i<5;i++){first.Add(memory.ExpectedDirection);memory.Direction(memory.ExpectedDirection);memory.Tick(.4f);}Check("random_memory_can_complete",memory.Won);memory.StartGame();memory.Tick(5.1f);bool different=false;for(int i=0;i<5;i++){different|=first[i]!=memory.ExpectedDirection;if(i==2){int previous=memory.Progress;memory.Direction((memory.ExpectedDirection+1)%4);Check("mistake_keeps_completed_steps",memory.Progress==previous);}memory.Direction(memory.ExpectedDirection);memory.Tick(.4f);}Check("replay_sequence_changes",different&&memory.Won);
